import{_ as e,o as n,c as s,a3 as t}from"./chunks/framework.WFmvnizL.js";const b=JSON.parse('{"title":"哪吒监控 V2 架构与数据流","description":"哪吒监控 V2 的文本架构说明，覆盖 Dashboard、Agent、前端、SQLite、可选 TSDB、gRPC 连接、服务探测、告警和远程运维数据流。","frontmatter":{"title":"哪吒监控 V2 架构与数据流","description":"哪吒监控 V2 的文本架构说明，覆盖 Dashboard、Agent、前端、SQLite、可选 TSDB、gRPC 连接、服务探测、告警和远程运维数据流。","outline":"deep"},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1785844584000}'),l={name:"guide/architecture.md"};function i(o,a,r,d,h,p){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="哪吒监控-v2-架构与数据流" tabindex="-1">哪吒监控 V2 架构与数据流 <a class="header-anchor" href="#哪吒监控-v2-架构与数据流" aria-label="Permalink to &quot;哪吒监控 V2 架构与数据流&quot;">​</a></h1><p>哪吒监控 V2 使用“一个 Dashboard 管理多个 Agent”的集中式拓扑。Dashboard 是控制面和展示入口，Agent 是部署在被监控节点上的数据采集与任务执行端。理解这条边界有助于正确设计域名、反向代理、权限、备份和故障排查。</p><h2 id="逻辑拓扑" tabindex="-1">逻辑拓扑 <a class="header-anchor" href="#逻辑拓扑" aria-label="Permalink to &quot;逻辑拓扑&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 / API 客户端</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          | HTTPS / WebSocket</span></span>
<span class="line"><span>          v</span></span>
<span class="line"><span>+------------------------+        通知提供商 / DNS API</span></span>
<span class="line"><span>| Dashboard              |---------------------&gt; 外部集成</span></span>
<span class="line"><span>| - 用户与管理前端       |</span></span>
<span class="line"><span>| - REST API / MCP       |</span></span>
<span class="line"><span>| - 告警与任务调度       |</span></span>
<span class="line"><span>| - 实时状态与权限控制   |</span></span>
<span class="line"><span>+-----------+------------+</span></span>
<span class="line"><span>            |        |</span></span>
<span class="line"><span>            |        +------&gt; SQLite（配置、用户和业务数据）</span></span>
<span class="line"><span>            |        +------&gt; 可选 TSDB（指标与服务监控历史）</span></span>
<span class="line"><span>            |</span></span>
<span class="line"><span>            | gRPC（可由 HTTPS 反向代理承载）</span></span>
<span class="line"><span>            v</span></span>
<span class="line"><span>     +------+------+------+</span></span>
<span class="line"><span>     | Agent | Agent | ... |</span></span>
<span class="line"><span>     +-------+-------+-----+</span></span>
<span class="line"><span>        |       |</span></span>
<span class="line"><span>        +-------&gt; 本机指标、网络检查、授权任务</span></span></code></pre></div><p>这是逻辑关系，不要求每个组件位于同一网络。关键条件是浏览器能够访问 Dashboard，且每个 Agent 能够访问 Dashboard 的 Agent 对接地址。</p><h2 id="dashboard-是什么角色" tabindex="-1">Dashboard 是什么角色？ <a class="header-anchor" href="#dashboard-是什么角色" aria-label="Permalink to &quot;Dashboard 是什么角色？&quot;">​</a></h2><p>Dashboard 承担以下职责：</p><ul><li>验证用户、API Token 和 Agent 连接身份。</li><li>接收 Agent 上报的主机信息、实时状态和任务结果。</li><li>维护服务器、分组、用户、服务、通知、任务、DDNS 和系统配置。</li><li>向用户前端、管理前端、REST API 和可选 MCP 入口提供数据。</li><li>评估服务状态与告警条件，并调用已配置的通知方式。</li><li>将终端、文件、任务、NAT 等授权请求转交到目标 Agent。</li></ul><p>因此，Dashboard 不只是只读图表。启用远程运维能力后，它属于高权限控制面，应限制管理入口、使用 TLS、保护密钥并保持更新。</p><h2 id="agent-是什么角色" tabindex="-1">Agent 是什么角色？ <a class="header-anchor" href="#agent-是什么角色" aria-label="Permalink to &quot;Agent 是什么角色？&quot;">​</a></h2><p>Agent 运行在每台被监控设备上，主要负责：</p><ul><li>读取操作系统可提供的主机和网络状态。</li><li>使用连接密钥与自身 UUID 接入 Dashboard。</li><li>按 <code>report_delay</code> 等配置报告状态。</li><li>执行被分配的 HTTP、Ping 或 TCP 服务检查。</li><li>在没有被禁用且调用者有权限时执行终端、文件、任务、更新或 NAT 相关操作。</li></ul><p>不需要远程操作的节点应使用 Agent 的 <code>disable_command_execute</code>、<code>disable_force_update</code>、<code>disable_nat</code> 等配置缩小能力范围。完整字段见 <a href="/configuration/agent.html">Agent 配置</a>。</p><h2 id="连接与反向代理" tabindex="-1">连接与反向代理 <a class="header-anchor" href="#连接与反向代理" aria-label="Permalink to &quot;连接与反向代理&quot;">​</a></h2><p>V2 的 Web 访问和 Agent 通信可以共用 Dashboard 监听端口，默认是 <code>8008</code>。实际部署通常有两种方式：</p><ol><li><strong>直接访问 Dashboard 端口</strong>：浏览器和 Agent 连接 <code>host:8008</code>。</li><li><strong>通过反向代理提供 HTTPS</strong>：代理将普通 HTTP、WebSocket 和 gRPC 请求转发到 Dashboard。</li></ol><p>反向代理必须正确支持 gRPC 和 WebSocket。当前 Agent/Dashboard 兼容 <code>Authorization</code> 和 <code>Grpc-Metadata-Authorization</code> 两种 gRPC 认证头；完整 Nginx、Caddy 和 CDN 注意事项见 <a href="/guide/q3.html">Dashboard 反向代理配置</a>及 <a href="/guide/q4.html">WebSocket 排障</a>。</p><p>如果公开访问域名和 Agent 通信域名不同，应分别设置 <code>dashboard_host</code> 和 <code>install_host</code>。它们还参与 OAuth2 回调 Host 与 NAT 保留域名判断，详见 <a href="/configuration/dashboard.html#dashboard-host">Dashboard 配置</a>。</p><h2 id="状态数据如何流动" tabindex="-1">状态数据如何流动？ <a class="header-anchor" href="#状态数据如何流动" aria-label="Permalink to &quot;状态数据如何流动？&quot;">​</a></h2><h3 id="主机状态" tabindex="-1">主机状态 <a class="header-anchor" href="#主机状态" aria-label="Permalink to &quot;主机状态&quot;">​</a></h3><p>Agent 将主机信息和状态流发送给 Dashboard。Dashboard 在内存中维护实时状态供页面和 API 查询；启用 TSDB 后，服务器历史指标会写入本地 TSDB。没有启用 TSDB 时，实时状态仍可使用，但服务器历史指标不可用，前端会锁定相应历史周期。</p><h3 id="服务监控" tabindex="-1">服务监控 <a class="header-anchor" href="#服务监控" aria-label="Permalink to &quot;服务监控&quot;">​</a></h3><p>Dashboard 根据服务的覆盖范围和特定服务器配置，将检查任务分配给 Agent。Agent 从自身网络位置访问 HTTP、ICMP 或 TCP 目标并返回结果。这样可以比较不同线路或地域到同一目标的可用性与延迟。</p><p>未启用 TSDB 时，服务监控历史从 SQLite 读取；启用 TSDB 后改为从 TSDB 查询。启用步骤和迁移限制见<a href="/guide/q15.html">如何启用 TSDB</a>。</p><h3 id="远程操作" tabindex="-1">远程操作 <a class="header-anchor" href="#远程操作" aria-label="Permalink to &quot;远程操作&quot;">​</a></h3><p>浏览器或 API 发起终端、文件、任务等请求后，Dashboard 先验证用户或 Token 权限，再通过 Agent 的任务或 IOStream 通道转发。终端、文件管理、NAT 和 MCP 文件传输会使用有限的 IOStream 配额；需要时应关闭闲置会话。</p><h2 id="数据存在哪里" tabindex="-1">数据存在哪里？ <a class="header-anchor" href="#数据存在哪里" aria-label="Permalink to &quot;数据存在哪里？&quot;">​</a></h2><ul><li><strong>SQLite</strong>：Dashboard 默认使用本地 SQLite 文件保存用户、配置和业务数据。</li><li><strong>内存</strong>：当前在线状态和运行时对象会在 Dashboard 内存中维护，进程重启后由 Agent 重新连接并报告。</li><li><strong>可选 TSDB</strong>：配置 <code>tsdb.data_path</code> 后启用内置时序存储，用于服务器指标和服务监控历史。</li><li><strong>外部服务</strong>：只有在配置相应通知、OAuth2 或 DDNS 提供商时，Dashboard 才会向这些服务发送请求；发送内容取决于具体模板和配置。</li></ul><p>备份时不能只保存容器定义。安装脚本部署通常需要备份 <code>/opt/nezha</code>，并在迁移前停止 Dashboard 以获得一致数据，见<a href="/guide/q5.html">备份与恢复</a>。</p><h2 id="常见架构选择" tabindex="-1">常见架构选择 <a class="header-anchor" href="#常见架构选择" aria-label="Permalink to &quot;常见架构选择&quot;">​</a></h2><h3 id="单域名部署" tabindex="-1">单域名部署 <a class="header-anchor" href="#单域名部署" aria-label="Permalink to &quot;单域名部署&quot;">​</a></h3><p>同一 HTTPS 域名同时服务浏览器和 Agent，配置最简单。反向代理必须同时正确处理 WebSocket 和 gRPC。</p><h3 id="访问域名与通信域名分离" tabindex="-1">访问域名与通信域名分离 <a class="header-anchor" href="#访问域名与通信域名分离" aria-label="Permalink to &quot;访问域名与通信域名分离&quot;">​</a></h3><p>公开访问域名可接入 CDN，Agent 通信域名直接回源或使用明确支持 gRPC 的代理。该方式能绕开部分 CDN 对长连接或 gRPC 的限制，但需要正确设置两个 Host。</p><h3 id="私有-dashboard" tabindex="-1">私有 Dashboard <a class="header-anchor" href="#私有-dashboard" aria-label="Permalink to &quot;私有 Dashboard&quot;">​</a></h3><p>通过 VPN、私有网络或访问控制层限制 Dashboard，适合不需要公开状态页的场景。必须确保所有 Agent 和管理员客户端仍能到达所需入口。</p><h2 id="上线前检查" tabindex="-1">上线前检查 <a class="header-anchor" href="#上线前检查" aria-label="Permalink to &quot;上线前检查&quot;">​</a></h2><ul><li><a href="/guide/dashboard.html">安装 Dashboard</a>并替换默认密码。</li><li>为公开入口启用 HTTPS，正确配置真实 IP 请求头和可信 Host。</li><li>只向必要用户开放终端、文件、任务、NAT、API 与 MCP 权限。</li><li>为 Agent 关闭不需要的执行能力。</li><li>备份 SQLite、配置和 TSDB 目录，并验证恢复过程。</li><li>阅读<a href="/guide/security.html">安全与隐私</a>和<a href="/guide/version-compatibility.html">版本与兼容性</a>。</li></ul>`,38)])])}const g=e(l,[["render",i]]);export{b as __pageData,g as default};
